declare(strict_types=1); @ini_set('display_errors','0'); header('Content-Type: application/json; charset=utf-8'); header('Cache-Control: no-store'); header('Access-Control-Allow-Origin: *');
function out(array $x,int $s=200):void{http_response_code($s);echo json_encode($x,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;} function ip(string $n,string $d=''):string{return trim((string)($_POST[$n]??$_GET[$n]??$d));}
$key=ip('key',ip('user_key'));$device=ip('device_id',ip('device'));if($key==='')out(['status'=>false,'message'=>'Missing key'],400);
try{$root=dirname(__DIR__,2);$public=$root.'/public/';$pf=$root.'/app/Config/Paths.php';if(!is_file($pf)||!is_dir($public))out(['status'=>false,'message'=>'Server framework not found'],500);if(!defined('FCPATH'))define('FCPATH',$public);@chdir($public);require_once $pf;$paths=new Config\Paths();$system=rtrim((string)$paths->systemDirectory,'\\/ ');if(is_file($system.'/bootstrap.php'))require_once $system.'/bootstrap.php';elseif(is_file($system.'/Boot.php')){require_once $system.'/Boot.php';if(class_exists('CodeIgniter\\Boot')&&method_exists('CodeIgniter\\Boot','bootConsole'))CodeIgniter\Boot::bootConsole($paths);}if(!function_exists('db_connect')&&is_file($system.'/Common.php'))require_once $system.'/Common.php';$db=db_connect();$row=$db->table('keys_code')->where('user_key',$key)->get()->getRowArray();if(!$row)out(['status'=>false,'message'=>'Invalid key']);if((int)($row['status']??1)!==1)out(['status'=>false,'message'=>'Key disabled']);if(!empty($row['expired_date'])&&strtotime((string)$row['expired_date'])<time())out(['status'=>false,'message'=>'Key expired']);$duration=max(1,(int)($row['duration']??1));$u=[];if(empty($row['expired_date']))$u['expired_date']=date('Y-m-d H:i:s',time()+$duration*86400);$devices=array_values(array_filter(array_map('trim',explode(',',(string)($row['devices']??'')))));$max=max(1,(int)($row['max_devices']??1));if($device!==''&&!in_array($device,$devices,true)){if(count($devices)>=$max)out(['status'=>false,'message'=>'Device limit reached']);$devices[]=$device;$u['devices']=implode(',',$devices);}if($u)$db->table('keys_code')->where('id_keys',$row['id_keys'])->update($u);out(['status'=>true,'message'=>'Key valid','key'=>$key,'game'=>$row['game']??'PUBG','expires_at'=>$u['expired_date']??($row['expired_date']??null),'max_devices'=>$max,'used_devices'=>count($devices)]);}catch(Throwable $e){out(['status'=>false,'message'=>'Server error'],500);}